  (20124,'pc-l13',10,'drill','Examples',null,null,'recognition','mc','peek',null,null,null,'Wala is a negation ("not") word.'),
  (20125,'pc-l13',11,'drill','Examples',null,null,'recognition','mc','peek',null,null,null,null),
